steps.function:
(args) => {
  // Poll the v3-mail worker inbox for the newest code email, then fetch its
  // body. Runs inside the v3-mail tab (same-origin, admin session cookie).
  const sinceId = Number(args.sinceId) || 0;
  return fetch('/emails?address=' + encodeURIComponent(args.email) + '&limit=3', { credentials: 'include' })
    .then(r => r.json())
    .then(d => {
      const rows = (d.results || []).filter(x => x.id > sinceId && /code/i.test(x.subject || ''));
      if (!rows.length) return { code: null, reason: 'no new code email yet' };
      const row = rows[0];
      return fetch('/emails/' + row.id, { credentials: 'include' })
        .then(r => r.json())
        .then(full => {
          const text = (full.text_body || '').trim();
          const m = text.match(/[A-Z0-9]{4,10}/) || (full.subject || '').match(/([A-Z0-9]{4,10})/);
          if (!m) return { code: null, reason: 'no code in body or subject', subject: full.subject };
          return { code: m[1], subject: full.subject, emailId: row.id, received: row.received_at };
        });
    })
    .catch(e => ({ code: null, error: String(e) }));
}
